import threading
import time
import keyboard

def listen_til_tryk():
    try:
        print("Tastetryk i gang!")
        keyboard.wait('q')
    except KeyboardInterrupt:
        print("Tastetryk stoppet.")
        print("Tastetryk i gang igen.")

def hovedprogram():
    print("Hovedprogram kører...")
    try:
        listen_til_tryk()
    except Exception as e:
        print(f"En uventet fejl opstod: {e}")
        print("Programmet fortsætter med at køre.")

if __name__ == "__main__":
    hovedprogram()
```
